def diff(a, b):
    out = []
    for k, v in b["cards"].items():
        if k not in a["cards"]: out.append(f"+card {k} {v}")
        elif a["cards"][k] != v: out.append(f"~card {k} {a['cards'][k][:2]} -> {v}")
    for k in a["cards"]:
        if k not in b["cards"]: out.append(f"-card {k}")
    for k, v in b["parts"].items():
        if a["parts"].get(k) != v: out.append(f"~part {k} {a['parts'].get(k)} -> {v}")
    if a["tracker"] != b["tracker"]: out.append(f"~tracker {a['tracker']} -> {b['tracker']}")
    return out

