    return {"cards": cards, "parts": parts, "events": len(s["events"]), "tracker": s["tracker"],
            "inbox": len(s["inbox_ids"]), "t": round(dt, 1)}

def diff(a, b):
    out = []
    for k, v in b["cards"].items():
        if k not in a["cards"]: out.append(f"+card {k} {v}")
        elif a["cards"][k] != v: out.append(f"~card {k} {a['cards'][k][:2]} -> {v}")
    for k in a["cards"]:
        if k not in b["cards"]: out.append(f"-card {k}")
    for k, v in b["parts"].items():
        if a["parts"].get(k) != v: out.append(f"~part {k} {a['parts'].get(k)} -> {v}")
    if a["tracker"] != b["tracker"]: out.append(f"~tracker {a['tracker']} -> {b['tracker']}")
    return out

def main():
    path = sys.argv[1]; src = Path(sys.argv[2]) if len(sys.argv) > 2 and sys.argv[2] != "-" else None
    before = snap()
    t = time.time()
    res = {"path": path}
    try:
        r = runner.drop(path, src); res["pipeline"] = r["pipeline"]; res["event"] = r["event"]["kind"]
    except Exception as e:
        traceback.print_exc(); res["drop_error"] = repr(e)
    res["t_pipeline"] = round(time.time() - t, 1)
    t = time.time()
    try:
        anchors.build_index(); papercheck.run(write=True, verbose=True)
        dc = datacheck.check(api.portal_root()); res["datacheck"] = [i["text"] for i in dc["issues"]]
    except Exception as e:
        traceback.print_exc(); res["papercheck_error"] = repr(e)
    res["t_papercheck"] = round(time.time() - t, 1)
    after = snap()
    res["t_state"] = after["t"]; res["events_delta"] = after["events"] - before["events"]
    res["diff"] = diff(before, after)
    print(json.dumps(res, indent=1, ensure_ascii=False, default=str))

if __name__ == "__main__":
    main()
